#include <iostream>
#include <boost/multiprecision/cpp_int.hpp>

using namespace std;
using boost::multiprecision::cpp_int;

cpp_int gcd(cpp_int a, cpp_int b) {
    while (b != 0) {
        cpp_int remainder = a % b;
        a = b;
        b = remainder;
    }
    return a;
}

int main() {
    cpp_int n;
    int k;

    if (!(cin >> n >> k)) {
        return 0;
    }

    cpp_int temp = 1;
    for (int i = 0; i < k; ++i) {
        temp *= 10;
    }

    cpp_int result = (n / gcd(n, temp)) * temp;
    cout << result;

    return 0;
}

